import {useEffect,useRef,useState,type FormEvent,type ReactNode} from 'react';
import {ArrowRight,ArrowUpRight,BarChart3,BookOpen,CalendarDays,Check,CheckCheck,ChevronDown,ChevronRight,ClipboardCheck,Download,FileSpreadsheet,FileText,FolderOpen,HardDrive,HelpCircle,Info,Layers,LayoutDashboard,Menu,MessageSquare,Plus,Printer,RotateCcw,Save,Search,Settings2,TrendingUp,Wallet,X,AlertTriangle,Clock3,Upload} from 'lucide-react';
import { Help } from './Help';
import source from './source-data.json';
import {buildSeries,cashRollforward,earnedFromQuantity,earnedValue,linearPlanned,validateWorkspace} from './core.mjs';
import {questions,formulaInfo} from './review-data';

const nav=[{id:'overview',title:'Resumen',icon:LayoutDashboard},{id:'budget',title:'Presupuesto',icon:Layers},{id:'schedule',title:'Programa de obra',icon:CalendarDays},{id:'progress',title:'Avance ejecutado',icon:ClipboardCheck},{id:'costs',title:'Costos reales',icon:Wallet},{id:'curve',title:'Curva S y desempeño',icon:TrendingUp},{id:'cash',title:'Flujo de efectivo',icon:BarChart3},{id:'reports',title:'Cortes y reportes',icon:FileText},{id:'sources',title:'Archivos de origen',icon:FolderOpen},{id:'review',title:'Revisión con el ingeniero',icon:MessageSquare}] as const;
type Page=typeof nav[number]['id'];
type Entry={id:string;week:number;amount:number;label:string;category?:string};
type Advance=Entry&{conceptId:string;quantity:number};
type Note={id:string;text:string;section:string;status:'Pendiente'|'Acordado'|'Descartado'};
type Snapshot={id:string;week:number;created:string;metrics:ReturnType<typeof earnedValue>;pending:number;changes?:number};
type Workspace={version:1;bac:number;advances:Advance[];costs:Entry[];notes:Note[];decisions:Record<string,string>;schedule:Record<string,{start:string;end:string}>;snapshots:Snapshot[];cashEntries:{id:string;type:'income'|'expense';label:string;amount:number}[]};
const isDemo = source.project.code === 'DEMO-001';
const STORAGE = isDemo ? 'trazal-mockup-demo-v1' : 'trazal-mockup-v1';
const empty:Workspace={version:1,bac:source.bac,advances:[],costs:[],notes:[],decisions:{},schedule:{},snapshots:[],cashEntries:[]};
const money=(n:number|null|undefined,d=2)=>n==null?'Sin base':new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',minimumFractionDigits:d,maximumFractionDigits:d}).format(n);
const number=(n:number,d=2)=>new Intl.NumberFormat('es-MX',{maximumFractionDigits:d}).format(n);
const percent=(n:number|null)=>n==null?'Sin base':`${number(n*100,1)}%`;
const date=(d:string)=>new Date(d+'T12:00:00').toLocaleDateString('es-MX',{day:'2-digit',month:'short'}).replace('.','');
const uid=()=>crypto.randomUUID();
function download(name:string,text:string,mime='application/json'){const url=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows:(string|number)[][]){return '\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');}
function Pill({children,tone='neutral'}:{children:ReactNode;tone?:string}){return <span className={`pill ${tone}`}>{children}</span>;}
function SourceNote({children}:{children:ReactNode}){return <div className="source-note"><FileSpreadsheet size={13}/><span>{children}</span></div>;}
function Empty({title,detail,action}:{title:string;detail:string;action?:ReactNode}){return <div className="empty"><div className="empty-symbol"><FolderOpen size={24}/></div><h3>{title}</h3><p>{detail}</p>{action}</div>;}
function Chart({series,cut,large=false}:{series:typeof source.weeks;cut:number;large?:boolean}){
 const [visible,setVisible]=useState({pv:true,ev:true,ac:true});const [hover,setHover]=useState<number|null>(null);
 const width=840,height=large?340:300,pad={l:65,r:22,t:24,b:36};const max=Math.ceil(Math.max(...series.flatMap(w=>[w.pv,w.ev,w.ac]))/2000000)*2000000;
 const x=(i:number)=>pad.l+(i/16)*(width-pad.l-pad.r);const y=(v:number)=>height-pad.b-v/max*(height-pad.t-pad.b);
 const colors={pv:'#B59B33',ev:'#5E7557',ac:'#BD735A'};const labels={pv:'Planeado · PV',ev:'Ejecutado · EV',ac:'Costo real · AC'};
 const chosen=hover===null?series[cut-1]:series[hover];
 return <div className="chart"><div className="chart-legend">{(['pv','ev','ac'] as const).map(k=><button key={k} aria-pressed={visible[k]} onClick={()=>setVisible({...visible,[k]:!visible[k]})}><i style={{background:colors[k],opacity:visible[k]?1:.2}}/>{labels[k]}</button>)}<span>Millones de MXN</span></div><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="Curva S de valores acumulados por semana"><defs><linearGradient id="ev-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#718567" stopOpacity=".13"/><stop offset="100%" stopColor="#718567" stopOpacity="0"/></linearGradient></defs>{[0,.25,.5,.75,1].map(v=><g key={v}><line x1={pad.l} y1={y(max*v)} x2={width-pad.r} y2={y(max*v)} stroke="#EAECE4" strokeDasharray={v?'3 4':''}/><text x={pad.l-14} y={y(max*v)+4} textAnchor="end">{number(max*v/1e6,1)} M</text></g>)}{visible.ev&&<path d={`M${x(0)},${y(0)} ${series.map((w,i)=>`L${x(i+1)},${y(w.ev)}`).join(' ')} L${x(16)},${y(0)} Z`} fill="url(#ev-fill)"/>}{(['pv','ev','ac'] as const).map(k=>visible[k]&&<polyline key={k} points={[[x(0),y(0)],...series.map((w,i)=>[x(i+1),y(w[k])])].map(p=>p.join(',')).join(' ')} fill="none" stroke={colors[k]} strokeWidth={k==='ev'?3:2.5} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={k==='pv'?'6 5':undefined}/>)}<line x1={x(cut)} x2={x(cut)} y1={pad.t} y2={height-pad.b} stroke="#A9AC9D" strokeDasharray="4 5"/>{series.map((w,i)=><g key={w.id}>{(i%2===1||i===0)&&<text x={x(i+1)} y={height-10} textAnchor="middle">S{w.id}</text>}{(['pv','ev','ac'] as const).map(k=>visible[k]&&w.id===cut&&<circle key={k} cx={x(i+1)} cy={y(w[k])} r="4" fill={colors[k]} stroke="white" strokeWidth="2"/>)}<rect x={x(i+1)-20} y={pad.t} width="40" height={height-pad.b-pad.t} fill="transparent" onMouseEnter={()=>setHover(i)} onMouseLeave={()=>setHover(null)}/></g>)}</svg><div className="chart-reading"><strong>{chosen.label} · {date(chosen.date)}</strong><span>PV {money(chosen.pv,0)}</span><span>EV {money(chosen.ev,0)}</span><span>AC {money(chosen.ac,0)}</span></div></div>;
}

export default function App(){
 const [page,setPage]=useState<Page>('overview');const [week,setWeek]=useState(12);const [workspace,setWorkspace]=useState<Workspace>(()=>{try{const raw=localStorage.getItem(STORAGE);return raw?validateWorkspace(JSON.parse(raw),source.concepts.map(c=>c.id)):structuredClone(empty);}catch{return structuredClone(empty);}});
 const [saved,setSaved]=useState(true);const [query,setQuery]=useState('');const [category,setCategory]=useState('Todas');const [toast,setToast]=useState('');const [drawer,setDrawer]=useState(false);const [modal,setModal]=useState<{kind:string;id?:string}|null>(null);const [error,setError]=useState('');const [importStep,setImportStep]=useState(0);const [reportId,setReportId]=useState('live');
 const dialog=useRef<HTMLDialogElement>(null);const restoreFocus=useRef<HTMLElement|null>(null);const fileInput=useRef<HTMLInputElement>(null);const menuButton=useRef<HTMLButtonElement>(null);
 const series=buildSeries(source.weeks,workspace.advances,workspace.costs) as typeof source.weeks;const current=series[week-1];const metrics=earnedValue({bac:workspace.bac,...current});
 const pending=questions.filter(q=>workspace.decisions[q.id]!=='Aclarado').length;const changes=workspace.advances.length+workspace.costs.length+Object.keys(workspace.schedule).length+(workspace.bac!==source.bac?1:0);
 const filtered=source.concepts.filter(c=>(category==='Todas'||c.category===category)&&`${c.title} ${c.code} ${c.description}`.toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es')));
 const cash=cashRollforward(source.cash) as Array<typeof source.cash[number]&{opening:number;net:number;closing:number}>;const activeConcept=source.concepts.find(c=>c.id===modal?.id)||source.concepts.find(c=>c.progress<1)||source.concepts[0];
 useEffect(()=>{try{localStorage.setItem(STORAGE,JSON.stringify(workspace));setSaved(true);}catch{setSaved(false);}},[workspace]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),3600);return()=>clearTimeout(t);}},[toast]);
 useEffect(()=>{if(modal){dialog.current?.showModal();document.body.style.overflow='hidden';}else{dialog.current?.close();document.body.style.overflow='';restoreFocus.current?.focus();}return()=>{document.body.style.overflow='';};},[modal]);
 useEffect(()=>{if(!drawer)return;const close=(e:KeyboardEvent)=>{if(e.key==='Escape'){setDrawer(false);menuButton.current?.focus();}};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close);},[drawer]);
 function go(p:Page){setPage(p);setQuery('');setCategory('Todas');setDrawer(false);window.scrollTo({top:0,behavior:'instant'});}
 function open(kind:string,id?:string){restoreFocus.current=document.activeElement as HTMLElement;setError('');setImportStep(0);setModal({kind,id});}
 function close(){setModal(null);setError('');}
 function update(f:(s:Workspace)=>Workspace){setWorkspace(s=>f(s));}
 function exportSession(){download('Trazal-sesion.json',JSON.stringify(workspace,null,2));setToast('Sesión exportada. Incluye simulaciones y observaciones.');}
 function exportBudget(){download('Trazal-presupuesto-referencia.csv',csv([['Clave','Concepto','Partida','Cantidad','Unidad','Importe original','P.U. deducido (por validar)'],...source.concepts.map(c=>[c.code,c.title,c.category,c.quantity,c.unit,c.amount,c.derivedPrice])]),'text/csv;charset=utf-8');}
 function exportReview(){download('Trazal-acuerdos-de-revision.md',`# Trazal · Revisión con el ingeniero\n\n## Criterios del Excel\n${questions.map(q=>`\n### ${q.title}\nEstado: ${workspace.decisions[q.id]||'Pendiente'}\n${q.detail}\nFuente: ${q.source}\n`).join('')}\n## Observaciones de la sesión\n${workspace.notes.map(n=>`- [${n.status}] ${n.section}: ${n.text}`).join('\n')||'Sin observaciones registradas.'}\n\n## Siguiente paso\nValidar un corte completo frente a los archivos originales y acordar el alcance de escritorio.\n`,'text/markdown;charset=utf-8');}
 async function loadSession(file:File){try{if(file.size>5e6)throw new Error('El archivo supera 5 MB.');const candidate=validateWorkspace(JSON.parse(await file.text()),source.concepts.map(c=>c.id));for(const c of source.concepts){const extra=candidate.advances.filter((a:Advance)=>a.conceptId===c.id).reduce((s:number,a:Advance)=>s+a.quantity,0);if(extra>c.quantity*(1-c.progress)+.000001)throw new Error(`El avance de ${c.title} supera el catálogo.`);}setWorkspace(candidate);setToast('Sesión recuperada en este navegador.');}catch(e){setToast(e instanceof Error?e.message:'No se pudo leer la sesión.');}}
 function addSnapshot(){update(s=>({...s,snapshots:[{id:uid(),week,created:new Date().toISOString(),metrics,pending,changes},...s.snapshots]}));setToast('Borrador de corte guardado con las cifras de este momento.');go('reports');}
 function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const data=new FormData(e.currentTarget);const val=(k:string)=>String(data.get(k)||'').trim();const amount=Number(val('amount'));try{
  if(modal?.kind==='advance'){const c=source.concepts.find(c=>c.id===val('concept'))!;const qty=Number(val('quantity'));const prior=workspace.advances.filter(a=>a.conceptId===c.id).reduce((s,a)=>s+a.quantity,0);if(qty+prior>c.quantity*(1-c.progress)+.000001)throw new Error('La cantidad supera el saldo del catálogo. Los adicionales necesitan una regla que aún debemos acordar.');const ev=earnedFromQuantity(qty,c.quantity,c.amount);update(s=>({...s,advances:[...s.advances,{id:uid(),week,amount:ev,label:c.title,conceptId:c.id,quantity:qty}]}));setToast('Avance de simulación agregado. EV e indicadores recalculados.');}
  if(modal?.kind==='cost'){if(!Number.isFinite(amount)||amount<=0)throw new Error('Escribe un importe mayor que cero.');update(s=>({...s,costs:[...s.costs,{id:uid(),week,amount,label:val('label'),category:val('category')}]}));setToast('Costo de simulación agregado al corte. AC recalculado.');}
  if(modal?.kind==='note'){update(s=>({...s,notes:[{id:uid(),text:val('text'),section:val('section'),status:'Pendiente'},...s.notes]}));setToast('Observación guardada para la reunión.');}
  if(modal?.kind==='schedule'){const start=val('start'),end=val('end');linearPlanned(activeConcept.amount,start,end,current.date);update(s=>({...s,schedule:{...s.schedule,[activeConcept.id]:{start,end}}}));setToast('Reprogramación guardada como escenario. La línea base original se conserva.');}
  if(modal?.kind==='settings'){const bac=Number(val('bac'));if(!Number.isFinite(bac)||bac<=0)throw new Error('El presupuesto de referencia debe ser mayor que cero.');update(s=>({...s,bac}));setToast('BAC del escenario actualizado.');}
  if(modal?.kind==='cash'){if(!Number.isFinite(amount)||amount<=0)throw new Error('Escribe un importe mayor que cero.');update(s=>({...s,cashEntries:[...s.cashEntries,{id:uid(),type:val('type') as 'income'|'expense',label:val('label'),amount}]}));setToast('Movimiento añadido al ejercicio de caja independiente.');}
  close();
 }catch(e){setError(e instanceof Error?e.message:'Revisa los datos.');}}
 const programSource = <>{source.files[3].name} · Fechas F:G y distribución diaria I:DJ. La primera fecha de la fila 16 es {date(source.concepts[0].daily[0].date)}.</>;
 const pageHelp: Record<Page, ReactNode> = {
  overview: 'El corte seleccionado reúne el valor planeado, el ejecutado y el costo real.',
  budget: <><p>Distribución del programa: {money(source.sourceTotals.schedule)}. Diferencia con el catálogo: {money(source.sourceTotals.budget - source.sourceTotals.schedule)}.</p><p>Presupuesto de referencia de la curva: {money(source.bac)}.</p><p className="help-source">{programSource}</p><button className="help-link" onClick={()=>go('sources')}>Revisar diferencias de origen <ArrowUpRight size={15}/></button></>,
  schedule: <><p>La tabla muestra el importe programado por mes. Reprogramar reparte el importe por día natural en un escenario aparte y conserva el plan original.</p><p className="help-source">{programSource}</p></>,
  progress: 'Los porcentajes de la tabla corresponden al acumulado del archivo de avance. Las cantidades que captures se suman al valor ejecutado desde el corte seleccionado.',
  costs: 'El costo real incluye costos directos e indirectos del flujo de origen. Los costos de prueba se agregan desde el corte seleccionado. Un costo puede incurrirse en una fecha distinta a la de su pago.',
  curve: 'La curva compara el valor planeado, el ejecutado y el costo real. Las proyecciones mantienen los supuestos del libro. Los cálculos de plazo requieren confirmar su unidad antes de usarlos como fechas de entrega.',
  cash: `El flujo de referencia corresponde a ${source.cashYear}. Los cortes de obra corresponden a 2026. El saldo inicial del flujo se supone en $0, por confirmar.`,
  reports: 'Guarda un borrador para conservar las cifras del corte. El selector de versión permite volver a un borrador o consultar las cifras actualizadas.',
  sources: 'Consulta cómo se relacionan los cuatro archivos y revisa las diferencias de origen.',
  review: 'Registra las decisiones de la reunión. Marcar un criterio como aclarado conserva las cifras originales.',
 };
 const renderMetrics = (full = false) => (
  <div className="metric-grid">
   {[
    { label: 'Valor planeado', value: metrics.pv, note: 'PV · Importe programado hasta el corte.' },
    { label: 'Valor ejecutado', value: metrics.ev, note: `EV · Valor de los trabajos ejecutados. Equivale al ${percent(metrics.progress)} del presupuesto de referencia.` },
    { label: 'Costo real', value: metrics.ac, note: 'AC · Costos directos e indirectos acumulados hasta el corte.' },
    { label: full ? 'Proyección al terminar' : 'Variación de costo', value: full ? metrics.eac : metrics.cv, note: full ? formulaInfo.eac.note : formulaInfo.cv.note },
   ].map((metric, index) => (
    <div className="metric" key={metric.label}>
     <div><span>{metric.label}</span><Help title={metric.label}>{metric.note}</Help></div>
     <strong className={!full && index === 3 && metrics.cv < 0 ? 'negative' : ''}>{money(metric.value, 0)}</strong>
    </div>
   ))}
  </div>
 );
 const renderFilters=()=> <div className="table-tools"><label className="search"><Search size={16}/><input aria-label="Buscar concepto" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar concepto o clave…"/></label><div className="tabs compact" aria-label="Filtrar partida">{['Todas','Terracerías','Drenaje','Pavimentos','Señalamiento'].map(cat=><button key={cat} aria-pressed={category===cat} onClick={()=>setCategory(cat)}>{cat}</button>)}</div><span>{filtered.length} conceptos</span></div>;
 const report=reportId==='live'?null:workspace.snapshots.find(s=>s.id===reportId);const reportMetrics=report?.metrics||metrics;const reportWeek=report?.week||week;

 return <div className="app"><a href="#content" className="skip">Saltar al contenido</a>{drawer&&<button className="nav-scrim" aria-label="Cerrar navegación" onClick={()=>setDrawer(false)}/>}
 <aside className={`sidebar ${drawer?'open':''}`}><button className="brand" onClick={()=>go('overview')} aria-label="Trazal, ir al resumen"><img src="/brand/symbol-mono.svg" alt=""/><span>trazal<small>CONTROL DE OBRA</small></span></button><div className="workspace-label">ESPACIO DE TRABAJO <span>01</span></div><button className="project-switch" onClick={()=>open('project')}><div className="project-icon"><Layers size={19}/></div><span>{source.project.short}<small>{source.project.name}</small></span><ChevronDown size={14}/></button><nav aria-label="Secciones del prototipo">{nav.map((n,i)=><button key={n.id} className={`${page===n.id?'active':''} ${i===8?'nav-separator':''}`} onClick={()=>go(n.id)} aria-current={page===n.id?'page':undefined}><n.icon size={18}/><span>{n.title}</span>{n.id==='review'&&<small>{pending}</small>}{page===n.id&&n.id!=='review'&&<i/>}</button>)}</nav><div className="sidebar-bottom"><button onClick={()=>open('guide')}><BookOpen size={17}/> Recorrido para la reunión<ArrowUpRight size={14}/></button><div className="local-status"><HardDrive size={16}/><span>Prototipo local<small>{saved?'Sesión guardada en este navegador':'No se pudo guardar. Exporta la sesión.'}</small></span><i className={saved?'':'error'}/></div></div></aside>
 <div className="shell"><header className="topbar"><div className="breadcrumb"><button ref={menuButton} className="icon-button mobile-menu" aria-label="Abrir navegación" onClick={()=>setDrawer(!drawer)}><Menu size={20}/></button><span>Obras</span><ChevronRight size={13}/><strong>{source.project.short}</strong><ChevronRight size={13}/><span>{nav.find(n=>n.id===page)?.title}</span></div><div className="top-actions"><Pill tone="yellow">{isDemo ? 'Demo · Datos ficticios' : 'Prototipo para revisión'}</Pill><button className="icon-button" onClick={()=>open('settings')} aria-label="Ajustar supuestos"><Settings2 size={18}/></button><button className="avatar" onClick={()=>open('guide')} aria-label="Abrir guía de revisión">TZ</button></div></header>
 <main id="content"><div className="page-heading"><div>
  <div className="title-with-help"><h1>{nav.find(n=>n.id===page)?.title}</h1><Help title={nav.find(n=>n.id===page)!.title}>{pageHelp[page]}</Help></div>
  {isDemo && <span className="mobile-data-label">Datos ficticios</span>}
  {changes > 0 && <Pill tone="olive">{changes} cambios de simulación</Pill>}
 </div><div className="page-actions">{!['sources','review','cash'].includes(page)&&<label className="cut-select"><CalendarDays size={16}/><select aria-label="Seleccionar corte" value={week} onChange={e=>setWeek(Number(e.target.value))}>{source.weeks.map(w=><option value={w.id} key={w.id}>Corte {String(w.id).padStart(2,'0')} · {date(w.date)} 2026</option>)}</select></label>}<button className="button primary" onClick={()=>open(page==='progress'?'advance':page==='costs'?'cost':page==='review'?'note':page==='schedule'?'guide':page==='cash'?'cash':'cut')}><Plus size={16}/>{page==='progress'?'Capturar avance':page==='costs'?'Registrar costo':page==='review'?'Nueva observación':page==='schedule'?'Ver recorrido':page==='cash'?'Probar movimiento':'Preparar corte'}</button></div></div>
 {page==='overview'&&<>
  {renderMetrics()}
  <div className="dashboard-grid"><section className="panel chart-panel"><div className="panel-heading"><div className="title-with-help"><h2>Curva S</h2><Help title="Curva S">Comparativo acumulado por semana. Se conserva el salto de la semana 9 para revisar la referencia de origen.</Help></div><button className="text-button" onClick={()=>go('curve')}>Ver análisis <ArrowUpRight size={15}/></button></div><Chart series={series} cut={week}/></section><section className="panel performance-panel"><div className="panel-heading"><h2>Desempeño del corte</h2></div><div className="performance-block"><span>Desempeño de costo <button className="help-trigger" onClick={()=>open('formula','cpi')} aria-label="Ayuda: desempeño de costo"><HelpCircle size={19}/></button></span><strong>{metrics.cpi==null?'—':number(metrics.cpi,3)}<Pill tone={metrics.cpi!=null&&metrics.cpi<1?'clay':'olive'}>{metrics.cpi==null?'Sin base':metrics.cpi<1?'Sobrecosto':'En presupuesto'}</Pill></strong><div className="index-scale"><i style={{left:`${Math.min(96,Math.max(4,(metrics.cpi||0)*50))}%`}}/><b/></div></div><div className="performance-block"><span>Desempeño de programa <button className="help-trigger" onClick={()=>open('formula','spi')} aria-label="Ayuda: desempeño de programa"><HelpCircle size={19}/></button></span><strong>{metrics.spi==null?'—':number(metrics.spi,3)}<Pill tone={metrics.spi!=null&&metrics.spi>=1?'olive':'clay'}>{metrics.spi==null?'Sin base':metrics.spi>=1?'Sobre lo previsto':'Bajo lo previsto'}</Pill></strong></div><div className="projection-mini"><TrendingUp size={19}/><div><span>Proyección al terminar</span><strong>{money(metrics.eac,0)}</strong></div><button className="help-trigger" onClick={()=>open('formula','eac')} aria-label="Ayuda: proyección al terminar"><HelpCircle size={19}/></button></div></section></div>
  <div className="bottom-grid"><section className="panel"><div className="panel-heading"><div className="title-with-help"><h2>Valor por partida</h2><Help title="Valor por partida">Porcentaje del importe ejecutado por partida, acumulado en el archivo de avance.</Help></div><button className="text-button" onClick={()=>go('progress')}>Ver conceptos <ArrowUpRight size={14}/></button></div>{['Terracerías','Drenaje','Pavimentos','Señalamiento'].map(cat=>{const cs=source.concepts.filter(c=>c.category===cat),total=cs.reduce((s,c)=>s+c.amount,0),ev=cs.reduce((s,c)=>s+c.earned,0);return <div className="category-progress" key={cat}><span>{cat}</span><div><i style={{width:`${ev/total*100}%`}}/></div><strong>{percent(ev/total)}</strong></div>;})}</section><section className="attention-card"><h2>Revisión del corte</h2><button className="text-button" onClick={()=>go('review')}>Abrir los {pending} criterios pendientes <ArrowRight size={15}/></button></section></div>
 </>}
 {page==='budget'&&<><div className="summary-strip"><div><span>Importes del catálogo</span><strong>{money(source.sourceTotals.budget)}</strong></div><button className="button" onClick={exportBudget}><Download size={15}/> Exportar CSV</button></div><section className="panel table-panel">{renderFilters()}<div className="table-scroll"><table><thead><tr><th>Clave / partida</th><th>Concepto</th><th className="num">Cantidad</th><th>Unidad</th><th className="num"><span className="column-with-help">P.U. deducido <Help title="Precio unitario deducido">Importe del concepto ÷ cantidad. El cálculo requiere validación con el ingeniero.</Help></span></th><th className="num">Importe original</th><th/></tr></thead><tbody>{filtered.map(c=><tr key={c.id}><td><span className="code">{c.code}</span><small>{c.category}</small></td><td><button className="concept-link" onClick={()=>open('concept',c.id)}>{c.title}</button></td><td className="num">{number(c.quantity)}</td><td>{c.unit}</td><td className="num muted">{money(c.derivedPrice,4)}</td><td className="num strong">{money(c.amount)}</td><td><button className="icon-button" onClick={()=>open('concept',c.id)} aria-label={`Detalle de ${c.title}`}><ArrowUpRight size={15}/></button></td></tr>)}</tbody></table></div>{filtered.length===0&&<Empty title="No encontramos ese concepto" detail="Prueba con otra clave o partida." action={<button className="button" onClick={()=>{setQuery('');setCategory('Todas');}}>Limpiar filtros</button>}/>}<div className="table-footer"><span>{filtered.length} de 30 conceptos</span><strong>Total filtrado {money(filtered.reduce((s,c)=>s+c.amount,0))}</strong></div></section></>}
 {page==='schedule'&&<><section className="panel table-panel">{renderFilters()}<div className="table-scroll"><table className="gantt-table"><thead><tr><th>Concepto</th><th>Inicio / término</th>{['Julio','Agosto','Septiembre','Octubre'].map(m=><th key={m}>{m} 2026</th>)}<th/></tr></thead><tbody>{filtered.map(c=>{const override=workspace.schedule[c.id];return <tr key={c.id}><td><strong>{c.title}</strong><small>{c.category}</small></td><td><span>{date(c.start)} — {date(c.end)}</span>{override&&<small className="olive-text">Propuesto: {date(override.start)} — {date(override.end)}</small>}</td>{[7,8,9,10].map(m=>{const total=c.daily.filter(d=>Number(d.date.slice(5,7))===m).reduce((s,d)=>s+d.amount,0);return <td key={m}><div className="gantt-cell"><i style={{width:`${Math.max(0,Math.min(100,total/c.amount*100))}%`}}/><span>{total?money(total,0):'—'}</span></div></td>})}<td><button className="text-button" onClick={()=>open('schedule',c.id)}>Reprogramar</button></td></tr>})}</tbody></table></div></section>{Object.keys(workspace.schedule).length>0&&<section className="panel scenario-plan"><div className="panel-heading"><div className="title-with-help"><h2>Escenario de reprogramación</h2><Help title="Importe del escenario">Importe acumulado hasta el {date(current.date)}, distribuido de manera uniforme entre las fechas propuestas. La curva original se conserva.</Help></div></div>{Object.entries(workspace.schedule).map(([id,s])=>{const c=source.concepts.find(c=>c.id===id)!;return <div className="ledger-row" key={id}><span><strong>{c.title}</strong><small>{date(s.start)} — {date(s.end)}</small></span><strong>{money(linearPlanned(c.amount,s.start,s.end,current.date))}</strong><button className="icon-button" aria-label={`Descartar reprogramación ${c.title}`} onClick={()=>update(w=>{const schedule={...w.schedule};delete schedule[id];return {...w,schedule};})}><X size={16}/></button></div>})}</section>}</>}
 {page==='progress'&&<><div className="summary-strip"><div><span>Ejecutado al corte {week}</span><strong>{money(metrics.ev)}</strong></div><div><span>Avances de simulación</span><strong>{workspace.advances.length} capturas</strong></div></div><section className="panel table-panel">{renderFilters()}<div className="table-scroll"><table><thead><tr><th>Concepto</th><th className="num">Cantidad catálogo</th><th className="num">Avance en libro real</th><th>Proporción del importe</th><th className="num"><span className="column-with-help">Valor ejecutado <Help title="Origen del valor ejecutado">{source.files[1].name} · DB de cada fila de importe; porcentaje deducido como valor ejecutado ÷ importe. Referencia total del archivo, no desglose por corte. Suma de importes: {money(source.concepts.reduce((s,c)=>s+c.earned,0))}; DB145 añade fracciones de avance y arroja {money(source.sourceTotals.earned)}. Diferencia por revisar: {money(source.sourceTotals.earned-source.concepts.reduce((s,c)=>s+c.earned,0))}.</Help></span></th><th/></tr></thead><tbody>{filtered.map(c=><tr key={c.id}><td><strong>{c.title}</strong><small>{c.code} · {c.category}</small></td><td className="num">{number(c.quantity)} {c.unit}</td><td className="num">{percent(c.progress)}</td><td><div className="table-progress"><i style={{width:`${Math.min(100,c.progress*100)}%`}}/></div></td><td className="num">{money(c.earned)}</td><td><button className="text-button" onClick={()=>open('advance',c.id)}>Capturar <Plus size={13}/></button></td></tr>)}</tbody></table></div></section><section className="panel"><div className="panel-heading"><h2>Capturas de esta simulación</h2><Pill>{workspace.advances.length}</Pill></div>{workspace.advances.length?workspace.advances.map(a=><div className="ledger-row" key={a.id}><span><strong>{a.label}</strong><small>Corte {a.week} · {number(a.quantity,4)} {source.concepts.find(c=>c.id===a.conceptId)?.unit}</small></span><strong>+ {money(a.amount)}</strong><button className="icon-button" aria-label={`Quitar captura ${a.label}`} onClick={()=>update(s=>({...s,advances:s.advances.filter(x=>x.id!==a.id)}))}><X size={16}/></button></div>):<Empty title="La siguiente captura empieza aquí" detail="Prueba una cantidad ejecutada y revisa cómo cambia la curva y el desempeño." action={<button className="button" onClick={()=>open('advance')}>Capturar avance <Plus size={15}/></button>}/>}</section></>}
 {page==='costs'&&<><div className="summary-strip"><div><span>Costo al corte {week}</span><strong>{money(metrics.ac)}</strong></div><div><span>Variación frente al EV</span><strong className={metrics.cv<0?'negative':''}>{money(metrics.cv)}</strong></div></div><div className="two-columns"><section className="panel table-panel"><div className="panel-heading"><div className="title-with-help"><h2>Costos por corte</h2><Help title="Costos por corte">El movimiento se calcula restando el acumulado anterior. Referencia: {source.files[2].name} · Hoja2!E25:E40.</Help></div><Pill>Origen</Pill></div><div className="table-scroll"><table><thead><tr><th>Corte</th><th className="num">Movimiento del periodo</th><th className="num">Acumulado AC</th></tr></thead><tbody>{source.weeks.slice(0,week).map((w,i)=><tr key={w.id}><td>Semana {w.id}<small>{date(w.date)} 2026</small></td><td className={`num ${w.ac-(source.weeks[i-1]?.ac||0)<0?'negative':''}`}>{money(w.ac-(source.weeks[i-1]?.ac||0))}{w.id===9&&<small>Revisar referencia</small>}</td><td className="num">{money(w.ac)}</td></tr>)}</tbody></table></div></section><section className="panel"><div className="panel-heading"><h2>Costos de prueba</h2><button className="icon-button" onClick={()=>open('cost')} aria-label="Agregar costo"><Plus size={18}/></button></div>{workspace.costs.length?workspace.costs.map(c=><div className="ledger-row" key={c.id}><span><strong>{c.label}</strong><small>{c.category} · corte {c.week}</small></span><strong>{money(c.amount)}</strong><button className="icon-button" onClick={()=>update(s=>({...s,costs:s.costs.filter(x=>x.id!==c.id)}))} aria-label={`Quitar costo ${c.label}`}><X size={15}/></button></div>):<Empty title="Hagamos una captura" detail="Importe, categoría y concepto. El costo actualiza AC y la proyección de la simulación." action={<button className="button primary" onClick={()=>open('cost')}>Registrar costo <Plus size={15}/></button>}/>}</section></div></>}
 {page==='curve'&&<>{renderMetrics(true)}<section className="panel chart-panel"><div className="panel-heading"><div className="title-with-help"><h2>Curva acumulada</h2><Help title="Origen de la serie">{source.files[2].name} · Hoja2!D25:F40. Los valores de los vínculos externos corresponden a la lectura guardada.</Help></div><button className="button" onClick={()=>download('Trazal-curva-s.csv',csv([['Semana','Fecha','PV','EV','AC'],...series.map(w=>[w.id,w.date,w.pv,w.ev,w.ac])]),'text/csv;charset=utf-8')}><Download size={15}/> Exportar serie</button></div><Chart series={series} cut={week} large/></section><div className="section-heading"><h2>Indicadores del corte</h2><button className="text-button" onClick={()=>open('settings')}>BAC: {money(workspace.bac,0)} <Settings2 size={15}/></button></div><div className="formula-grid">{Object.entries(formulaInfo).map(([key,f])=>{const value=metrics[key as keyof typeof metrics];const isPct=key.includes('Percent');const isRatio=['cpi','spi','tcpi','tc','tcPlan'].includes(key);return <article className="formula-card" key={key}><span>{f.label}<button className="help-trigger" onClick={()=>open('formula',key)} aria-label={`Ayuda: ${f.label}`}><HelpCircle size={19}/></button></span><strong>{value==null?'Sin base':isPct?percent(value):isRatio?number(value,4):money(value,0)}</strong></article>})}</div></>}
 {page==='cash'&&<><div className="metric-grid cash-metrics">{[{label:'Entradas registradas',n:source.cash.reduce((s,m)=>s+m.income,0)},{label:'Salidas registradas',n:source.cash.reduce((s,m)=>s+m.expense,0)},{label:'Saldo final con apertura $0',n:cash.at(-1)!.closing}].map(x=><div className="metric" key={x.label}><span>{x.label}</span><strong>{money(x.n,0)}</strong></div>)}</div><section className="panel table-panel"><div className="panel-heading"><div className="title-with-help"><h2>Movimientos mensuales</h2><Help title="Cálculo del saldo">Saldo final = saldo inicial + entradas − salidas. Hoja de flujo: entradas en filas 6:11, salidas en fila 261 y agrupación por mes en F:HM.</Help></div><Pill>{source.cashYear}</Pill></div><div className="table-scroll"><table><thead><tr><th>Mes</th><th className="num">Saldo inicial</th><th className="num">Entradas</th><th className="num">Salidas</th><th className="num">Flujo neto</th><th className="num">Saldo final</th></tr></thead><tbody>{cash.map(m=><tr key={m.month}><td><strong>{m.month}</strong></td><td className="num">{money(m.opening)}</td><td className="num olive-text">{money(m.income)}</td><td className="num">{money(m.expense)}</td><td className={`num ${m.net<0?'negative':''}`}>{money(m.net)}</td><td className={`num strong ${m.closing<0?'negative':''}`}>{money(m.closing)}</td></tr>)}</tbody></table></div></section><div className="two-columns"><section className="panel"><div className="panel-heading"><div className="title-with-help"><h2>Estado de resultados</h2><Help title="Origen de resultados">Importes de todo el periodo del libro, celdas H9:H44 de la hoja de resultados. Los impuestos se muestran como fueron registrados.</Help></div></div>{[['Ingresos',source.profit.sales],['Costo de venta',-source.profit.direct],['Utilidad bruta',source.profit.gross],['Gastos de operación',-source.profit.operation],['Utilidad de operación',source.profit.operatingProfit],['ISR registrado',-source.profit.isr],['PTU registrada',-source.profit.ptu],['Resultado neto',source.profit.net]].map(([name,n])=><div className="profit-row" key={name}><span>{name}</span><strong>{money(Number(n))}</strong></div>)}</section><section className="panel"><div className="panel-heading"><div className="title-with-help"><h2>Movimientos de prueba</h2><Help title="Saldo de prueba">Este ejercicio empieza en $0 y se lleva por separado del flujo de referencia.</Help></div><button className="icon-button" onClick={()=>open('cash')} aria-label="Agregar movimiento de caja"><Plus size={17}/></button></div>{workspace.cashEntries.length?workspace.cashEntries.map(e=><div className="ledger-row" key={e.id}><span><strong>{e.label}</strong><small>{e.type==='income'?'Entrada':'Salida'} de prueba</small></span><strong>{e.type==='income'?'+':'−'}{money(e.amount)}</strong><button className="icon-button" onClick={()=>update(s=>({...s,cashEntries:s.cashEntries.filter(x=>x.id!==e.id)}))} aria-label={`Quitar movimiento ${e.label}`}><X size={15}/></button></div>):<Empty title="Una caja de prueba" detail="Ensaya un anticipo, una estimación cobrada o un pago. Este ejercicio no modifica los datos financieros originales."/>}<div className="table-footer"><span>Saldo del ejercicio</span><strong>{money(workspace.cashEntries.reduce((s,e)=>s+(e.type==='income'?e.amount:-e.amount),0))}</strong></div></section></div></>}
 {page==='reports'&&<><div className="report-toolbar"><label>Versión del reporte<select value={reportId} onChange={e=>setReportId(e.target.value)} aria-label="Versión del reporte"><option value="live">Corte actual · cifras en vivo</option>{workspace.snapshots.map(s=><option value={s.id} key={s.id}>Corte {s.week} · guardado {new Date(s.created).toLocaleString('es-MX')}</option>)}</select></label><button className="button" onClick={addSnapshot}><Save size={15}/> Guardar borrador</button><button className="button" onClick={()=>download(`Trazal-corte-${reportWeek}.json`,JSON.stringify({project:source.project,week:reportWeek,metrics:reportMetrics,status:'Borrador de revisión',pending:report?.pending??pending,source:source.files[2].name + ' + simulaciones explícitas'},null,2))}><Download size={15}/> Exportar datos</button><button className="button primary" onClick={()=>window.print()}><Printer size={15}/> Imprimir / PDF</button></div><article className="report-sheet" id="report"><div className="report-header"><img src="/brand/horizontal-mono.svg" alt="Trazal"/><div>REPORTE DE CONTROL DE OBRA<strong>Corte {String(reportWeek).padStart(2,'0')}</strong></div></div><div className="report-title"><span className="eyebrow">{source.project.short} · {source.project.location}</span><h2>{source.project.name}</h2><p>Subtramo {source.project.section} · {date(source.weeks[reportWeek-1].date)} de 2026</p><Pill tone="yellow">Borrador para revisión con el ingeniero</Pill></div><div className="report-numbers">{[['Planeado / PV',reportMetrics.pv],['Ejecutado / EV',reportMetrics.ev],['Costo real / AC',reportMetrics.ac]].map(([label,n])=><div key={label}><span>{label}</span><strong>{money(Number(n))}</strong></div>)}</div><div className="report-results">{[['CPI',reportMetrics.cpi],['SPI',reportMetrics.spi],['EAC',reportMetrics.eac],['ETC',reportMetrics.etc],['VAC',reportMetrics.vac]].map(([label,n])=><div key={label}><span>{label}</span><strong>{n==null?'Sin base':['CPI','SPI'].includes(String(label))?number(Number(n),4):money(Number(n))}</strong></div>)}</div><div className="title-with-help report-method"><h3>Base del reporte</h3><Help title="Base del reporte">Presupuesto de referencia: {money(reportMetrics.bac)}. La proyección supone que se mantiene el desempeño de costo del corte.</Help></div><p className="report-print-detail">BAC utilizado: {money(reportMetrics.bac)}. Valores del corte recuperados de la curva original{(report?.changes??changes)?' con capturas de simulación':''}. EAC supone que se mantiene el CPI. Las cifras se presentan para validar el proceso.</p><h3>Pendientes de validación</h3><p>{report?.pending??pending} criterios pendientes al guardar este reporte. Revisar presupuesto base, calendario, referencias de semana 9 y definición del costo real.</p><div className="report-signatures"><span>Elaboró<br/><i/></span><span>Revisó<br/><i/></span></div><footer>TRAZAL · PROTOTIPO DE ESCRITORIO <span>{isDemo ? 'Datos ficticios' : 'Fuente: archivos de la obra'} · Documento de trabajo</span></footer></article></>}
 {page==='sources'&&<><div className="section-heading"><h2>Libros de trabajo</h2><button className="button" onClick={()=>open('import')}><Upload size={16}/> Recorrer importación</button></div><div className="file-grid">{source.files.map((f,i)=><section className="panel file-card" key={f.name}><div className="file-card-top"><FileSpreadsheet size={26}/><Pill>{f.name.endsWith('.xlsx')?'XLSX':'XLS'}</Pill></div><div className="title-with-help"><h3>{f.name}</h3><Help title="Contenido del libro">{i===0?'Flujo diario, resultados, balance y anexos. Se leyeron valores guardados; no se validaron las fórmulas internas del XLS.':i===1?'Fracciones de avance por concepto y su valuación sobre el importe del presupuesto.':i===2?'Series acumuladas de PV, AC y EV e indicadores de costo, programa y proyección.':'Catálogo de 30 conceptos, fechas e importes distribuidos diariamente.'}</Help></div><details><summary>{f.sheets.length} {f.sheets.length===1?'hoja analizada':'hojas analizadas'} <ChevronDown size={13}/></summary>{f.sheets.map(s=><div className="sheet-line" key={s.name}><span>{s.name}</span><small>{s.rows} filas · {s.columns} columnas</small></div>)}</details></section>)}</div><div className="section-heading"><div><span className="eyebrow">REVISIÓN DE CONSISTENCIA</span><h2>Lo que necesitamos aclarar.</h2></div><button className="text-button" onClick={()=>go('review')}>Registrar acuerdos <ArrowUpRight size={15}/></button></div>{questions.filter(q=>q.id!=='scope').map(q=><div className="source-issue" key={q.id}><AlertTriangle size={18}/><div><div className="title-with-help"><h3>{q.title}</h3><Help title={q.title}><p>{q.detail}</p><p className="help-source">{q.source}</p></Help></div></div><Pill tone="yellow">{workspace.decisions[q.id]||'Pendiente'}</Pill></div>)}</>}
 {page==='review'&&<><div className="review-summary"><div><span className="eyebrow">SESIÓN CON EL INGENIERO</span><h2>Primero el proceso.<br/>Después, la aplicación.</h2></div><div className="review-count"><strong>{questions.length-pending}<span>/{questions.length}</span></strong><p>criterios aclarados</p><button className="button" onClick={exportReview}><Download size={15}/> Exportar acuerdos</button></div></div><div className="section-heading"><h2>Criterios del cálculo y del trabajo</h2></div><div className="question-list">{questions.map((q,i)=><article className="question" key={q.id}><span className="question-index">{String(i+1).padStart(2,'0')}</span><div><div className="title-with-help"><h3>{q.title}</h3><Help title={q.title}><p>{q.detail}</p><p className="help-source">{q.source}</p></Help></div></div><div><Pill tone={q.priority==='Alta'?'clay':'neutral'}>Prioridad {q.priority.toLowerCase()}</Pill><select aria-label={`Estado: ${q.title}`} value={workspace.decisions[q.id]||'Pendiente'} onChange={e=>update(s=>({...s,decisions:{...s.decisions,[q.id]:e.target.value}}))}>{['Pendiente','Aclarado','Cambiar'].map(o=><option key={o}>{o}</option>)}</select><button className="text-button" onClick={()=>open('note',q.id)}>Anotar respuesta <Plus size={13}/></button></div></article>)}</div><div className="section-heading"><h2>Observaciones y acuerdos</h2><button className="text-button" onClick={()=>open('note')}>Agregar observación <Plus size={15}/></button></div>{workspace.notes.length?<div className="notes-grid">{workspace.notes.map(n=><article className="panel note-card" key={n.id}><div><Pill>{n.section}</Pill><button className="icon-button" aria-label={`Eliminar observación ${n.text.slice(0,25)}`} onClick={()=>update(s=>({...s,notes:s.notes.filter(x=>x.id!==n.id)}))}><X size={14}/></button></div><p>{n.text}</p><select aria-label={`Estado de observación ${n.text.slice(0,25)}`} value={n.status} onChange={e=>update(s=>({...s,notes:s.notes.map(x=>x.id===n.id?{...x,status:e.target.value as Note['status']}:x)}))}>{['Pendiente','Acordado','Descartado'].map(o=><option key={o}>{o}</option>)}</select></article>)}</div>:<section className="panel"><Empty title="Aquí se queda lo que aprendamos" detail="Anota cambios de pantalla, reglas de cálculo, datos faltantes o reportes que necesite el ingeniero." action={<button className="button primary" onClick={()=>open('note')}>Primera observación <Plus size={15}/></button>}/></section>}<div className="scope-grid"><div><CheckCheck size={21}/><h3>Probar ahora</h3><p>Catálogo, programa, captura, valor ganado, flujo, reporte y revisión de fuentes.</p></div><div><Clock3 size={21}/><h3>Definir para escritorio</h3><p>Archivo por obra, respaldo real, importador general, reglas de redondeo, instalador y licencias.</p></div><div><MessageSquare size={21}/><h3>Confirmar alcance</h3><p>Precios unitarios detallados, adicionales, estimaciones, impuestos, colaboración y contabilidad.</p></div></div></>}
 <footer className="app-footer"><span><HardDrive size={13}/> Datos y cambios de prueba en este navegador</span><div><button onClick={exportSession}>Exportar sesión <Download size={13}/></button><button onClick={()=>open('note')}>Anotar observación <MessageSquare size={13}/></button></div></footer></main></div>
 <dialog ref={dialog} className={`modal ${modal?.kind==='concept'||modal?.kind==='guide'||modal?.kind==='import'?'wide':''}`} onCancel={e=>{e.preventDefault();close();}} onClick={e=>{if(e.target===e.currentTarget)close();}}><header><span className="eyebrow">TRAZAL / {modal?.kind==='concept'?'TRAZABILIDAD':'ESPACIO DE PRUEBA'}</span><button className="icon-button" aria-label="Cerrar ventana" onClick={close}><X size={20}/></button></header>
 {modal?.kind==='advance'&&<form onSubmit={submit}><div className="title-with-help"><h2>Capturar avance</h2><Help title="Valuación del avance">Cantidad capturada ÷ cantidad de catálogo × importe original. La cantidad base ejecutada se deduce del porcentaje del archivo. La captura se agrega desde el corte {week}.</Help></div><label>Concepto<select name="concept" defaultValue={activeConcept.id}>{source.concepts.map(c=><option key={c.id} value={c.id}>{c.title} · {c.unit} · saldo {number(c.quantity*(1-c.progress)-workspace.advances.filter(a=>a.conceptId===c.id).reduce((s,a)=>s+a.quantity,0),4)}</option>)}</select></label><label>Cantidad ejecutada adicional<input name="quantity" type="number" step="any" min="0.000001" required placeholder="0.00" autoFocus/></label>{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="button" onClick={close}>Cancelar</button><button className="button primary" type="submit">Agregar a simulación <Check size={16}/></button></div></form>}
 {modal?.kind==='cost'&&<form onSubmit={submit}><div className="title-with-help"><h2>Registrar costo</h2><Help title="Costo de prueba">El importe se agrega al costo acumulado desde el corte {week}. Captúralo en la misma base que AC. El tratamiento de IVA y pagos requiere validación.</Help></div><label>Descripción<input name="label" required maxLength={120} placeholder="Ej. Suministro de concreto"/></label><div className="form-grid"><label>Categoría<select name="category"><option>Materiales</option><option>Mano de obra</option><option>Maquinaria</option><option>Indirectos</option><option>Subcontratos</option></select></label><label>Importe MXN<input type="number" name="amount" min="0.01" step="0.01" required placeholder="0.00"/></label></div>{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button className="button" type="button" onClick={close}>Cancelar</button><button className="button primary">Agregar costo <Check size={16}/></button></div></form>}
 {modal?.kind==='note'&&<form onSubmit={submit}><h2>Anotar una observación</h2><p className="modal-intro">Guarda lo que nos diga el ingeniero sin salir del recorrido.</p><label>Sobre qué tema<select name="section" defaultValue={modal.id?'Criterios del Excel':nav.find(n=>n.id===page)?.title}><option>Criterios del Excel</option>{nav.map(n=><option key={n.id}>{n.title}</option>)}<option>Aplicación de escritorio</option></select></label><label>Respuesta, cambio o necesidad<textarea name="text" required rows={5} maxLength={2500} defaultValue={modal.id?`${questions.find(q=>q.id===modal.id)?.title}\n\n`:''} placeholder="Qué funciona, qué cambia y cómo debería resolverse…"/></label><div className="modal-actions"><button className="button" type="button" onClick={close}>Cancelar</button><button className="button primary">Guardar observación <Check size={16}/></button></div></form>}
 {modal?.kind==='schedule'&&<form onSubmit={submit}><div className="title-with-help"><h2>Ensayar una reprogramación</h2><Help title="Cálculo del escenario">Reparte {money(activeConcept.amount)} de manera uniforme por día natural. El cálculo no incluye precedencias ni rendimientos. La curva conserva su valor planeado original.</Help></div><p className="modal-intro">{activeConcept.title}. Las fechas originales y su distribución diaria se conservan.</p><div className="form-grid"><label>Inicio propuesto<input type="date" name="start" required defaultValue={workspace.schedule[activeConcept.id]?.start||activeConcept.start}/></label><label>Término propuesto<input type="date" name="end" required defaultValue={workspace.schedule[activeConcept.id]?.end||activeConcept.end}/></label></div>{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="button" onClick={close}>Cancelar</button><button className="button primary">Guardar escenario</button></div></form>}
 {modal?.kind==='settings'&&<form onSubmit={submit}><h2>Supuestos del escenario</h2><p className="modal-intro">Cambia el BAC para comparar su efecto en la proyección. No modifica los importes del catálogo ni la distribución de PV.</p><label>Presupuesto de referencia · BAC<input name="bac" type="number" step="0.01" min="0.01" defaultValue={workspace.bac} required/></label><div className="reference-values"><span>Curva original <strong>{money(source.bac)}</strong></span><span>Suma del catálogo <strong>{money(source.sourceTotals.budget)}</strong></span><span>Distribución del programa <strong>{money(source.sourceTotals.schedule)}</strong></span></div><p className="modal-intro">Redondeo de presentación: 2 decimales. Se conserva la precisión de las fuentes para reproducir sus fórmulas. Política final pendiente.</p>{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="button" onClick={close}>Cancelar</button><button className="button primary">Aplicar al escenario</button></div></form>}
 {modal?.kind==='cash'&&<form onSubmit={submit}><h2>Probar un movimiento de caja</h2><p className="modal-intro">Ejercicio independiente del flujo histórico. Apertura de prueba: $0.</p><label>Descripción<input name="label" required placeholder="Ej. Anticipo recibido" maxLength={120}/></label><div className="form-grid"><label>Tipo<select name="type"><option value="income">Entrada</option><option value="expense">Salida</option></select></label><label>Importe MXN<input name="amount" type="number" min="0.01" step="0.01" required/></label></div>{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button className="button" type="button" onClick={close}>Cancelar</button><button className="button primary">Agregar movimiento</button></div></form>}
 {modal?.kind==='concept'&&<><h2>{activeConcept.title}</h2><p className="modal-intro">{activeConcept.code} · {activeConcept.category}</p><div className="detail-grid"><div><span>Cantidad de catálogo</span><strong>{number(activeConcept.quantity)} {activeConcept.unit}</strong></div><div><span>Importe original</span><strong>{money(activeConcept.amount)}</strong></div><div><span>P.U. deducido</span><strong>{money(activeConcept.derivedPrice,4)}</strong></div><div><span>Ejecutado en el libro real</span><strong>{money(activeConcept.earned)}</strong></div></div><h3>Descripción de origen</h3><p className="original-description">{activeConcept.description}</p><SourceNote>Programa · B{activeConcept.row}:G{activeConcept.row}; importe G{activeConcept.row+1}. Real · DB{activeConcept.row+1}. Algunos caracteres ya están dañados en los originales.</SourceNote><div className="formula-explain"><strong>Regla propuesta de valuación</strong><code>{money(activeConcept.amount)} ÷ {number(activeConcept.quantity)} {activeConcept.unit} = {money(activeConcept.derivedPrice,4)} / {activeConcept.unit}</code><p>Conservar el importe original evita alterar el presupuesto al redondear un P.U. que no viene explícito en la hoja.</p></div><div className="modal-actions"><button className="button" onClick={()=>open('note')}>Anotar observación</button><button className="button primary" onClick={()=>open('advance',activeConcept.id)}>Probar una captura <Plus size={15}/></button></div></>}
 {modal?.kind==='formula'&&<><h2>{formulaInfo[modal.id!].label}</h2><p className="modal-intro">Corte {week} · {date(current.date)} de 2026</p><div className="formula-explain large"><code>{formulaInfo[modal.id!].formula}</code><p>{formulaInfo[modal.id!].note}</p></div><div className="reference-values">{[['BAC',metrics.bac],['PV',metrics.pv],['EV',metrics.ev],['AC',metrics.ac]].map(([k,v])=><span key={k}>{k}<strong>{money(Number(v))}</strong></span>)}</div><SourceNote>{source.files[2].name} · Hoja1!{formulaInfo[modal.id!].cell}</SourceNote><div className="modal-actions"><button className="button" onClick={()=>open('note','forecast')}>Anotar duda</button><button className="button primary" onClick={close}>Entendido</button></div></>}
 {modal?.kind==='cut'&&<><h2>Preparar el corte {week}</h2><p className="modal-intro">Una fotografía de las cifras de esta sesión. El borrador conserva los criterios pendientes para revisarlos con el ingeniero.</p><div className="cut-checklist"><span><Check size={17}/> Catálogo y serie de origen disponibles</span><span><Check size={17}/> Indicadores recalculados con el escenario actual</span><span><AlertTriangle size={17}/> {pending} criterios aún por aclarar</span></div><div className="reference-values"><span>Planeado<strong>{money(metrics.pv)}</strong></span><span>Ejecutado<strong>{money(metrics.ev)}</strong></span><span>Costo<strong>{money(metrics.ac)}</strong></span></div><div className="modal-actions"><button className="button" onClick={()=>{close();go('review');}}>Revisar pendientes</button><button className="button primary" onClick={()=>{close();addSnapshot();}}>Guardar borrador <Save size={15}/></button></div></>}
 {modal?.kind==='project'&&<><h2>Una obra, en tu equipo.</h2><p className="modal-intro">Este sitio es una maqueta para conversar sobre la futura aplicación de escritorio. {isDemo ? 'Usa datos ficticios para probar capturas y reportes.' : 'Usa extractos de los Excel de la obra para probar capturas y reportes.'}</p><div className="reference-values"><span>Obra<strong>{source.project.code} · {source.project.short}</strong></span><span>Archivo de escritorio propuesto<strong>Un archivo por obra</strong></span><span>Persistencia de esta maqueta<strong>Solo este navegador</strong></span></div><div className="panel-note"><HardDrive size={18}/><p>Exporta la sesión antes de cambiar de computadora o limpiar el navegador. SQLite, respaldos automáticos, licencias y sincronización todavía no están implementados.</p></div><div className="session-buttons"><button className="button primary" onClick={exportSession}><Download size={15}/> Exportar sesión</button><button className="button" onClick={()=>fileInput.current?.click()}><Upload size={15}/> Abrir sesión JSON</button><button className="text-button" onClick={()=>open('reset')}><RotateCcw size={14}/> Restablecer pruebas</button></div></>}
 {modal?.kind==='reset'&&<><h2>Restablecer esta sesión</h2><p className="modal-intro">Se borrarán las capturas de prueba, observaciones, acuerdos y cortes guardados en este navegador. Los archivos Excel originales se conservan.</p><div className="modal-actions"><button className="button" onClick={exportSession}>Exportar antes</button><button className="button" onClick={close}>Cancelar</button><button className="button primary" onClick={()=>{setWorkspace(structuredClone(empty));setReportId('live');setWeek(12);close();setToast('Sesión restablecida a los valores originales.');}}>Restablecer</button></div></>}
 {modal?.kind==='guide'&&<><h2>El recorrido de la reunión.</h2><p className="modal-intro">Usen un corte conocido por el ingeniero. En cada paso, comparen qué hace hoy con lo que propone la maqueta.</p><div className="guide-list">{[{p:'sources',title:'1. Confirmar la información',text:'¿Estos son los archivos vigentes? ¿Cuál manda cuando no coinciden?'},{p:'budget',title:'2. Revisar presupuesto y programa',text:'¿Cómo define las cantidades, importes, fechas y línea base?'},{p:'progress',title:'3. Probar una captura de campo',text:'¿Captura cantidades, porcentajes o generadores? ¿Quién valida?'},{p:'costs',title:'4. Registrar un costo real',text:'¿De qué documento viene? ¿Se registra al incurrir o al pagar?'},{p:'curve',title:'5. Explicar el resultado',text:'¿Le ayudan los índices? ¿Cuáles entrega a dirección?'},{p:'reports',title:'6. Preparar el reporte',text:'¿Qué formato debe salir? ¿Qué firmas y desglose necesita?'},{p:'review',title:'7. Acordar el siguiente paso',text:'Exporten observaciones y definan las reglas antes de construir escritorio.'}].map(s=><button key={s.p} onClick={()=>{close();go(s.p as Page);}}><div><strong>{s.title}</strong><p>{s.text}</p></div><ArrowUpRight size={18}/></button>)}</div></>}
 {modal?.kind==='import'&&<><h2>Así proponemos importar.</h2><p className="modal-intro">Recorrido ilustrativo con los cuatro archivos ya analizados. El importador de otros Excel se construirá después de validar el formato.</p><div className="import-steps">{['Elegir archivos','Reconocer columnas','Revisar diferencias'].map((x,i)=><span className={i===importStep?'active':''} key={x}>{i+1}. {x}</span>)}</div>{importStep===0?<div className="import-files">{source.files.map(f=><div key={f.name}><FileSpreadsheet size={19}/><span>{f.name}</span><Check size={16}/></div>)}</div>:importStep===1?<div className="reference-values"><span>Clave de concepto<strong>Columna B</strong></span><span>Descripción<strong>Columna C</strong></span><span>Cantidad / unidad<strong>Columnas D / E</strong></span><span>Importe del concepto<strong>Columna G, fila siguiente</strong></span><span>Distribución diaria<strong>I:DJ del programa</strong></span><span>Identidad del registro<strong>Partida + clave + fila de origen</strong></span><p>Una misma clave aparece en partidas distintas; no se deben fusionar conceptos solo por el código.</p></div>:<div className="cut-checklist"><span><Check size={17}/> 30 conceptos con su origen conservado</span><span><AlertTriangle size={17}/> BAC, fechas, redondeo y referencias pendientes</span><span><Info size={17}/> Los archivos originales no se reemplazan</span></div>}<div className="modal-actions">{importStep>0&&<button className="button" onClick={()=>setImportStep(importStep-1)}>Anterior</button>}<button className="button primary" onClick={()=>{if(importStep<2)setImportStep(importStep+1);else{close();go('review');}}}>{importStep<2?'Continuar':'Revisar criterios'} <ArrowRight size={15}/></button></div></>}
 </dialog><input ref={fileInput} type="file" accept="application/json,.json" hidden onChange={e=>{const f=e.target.files?.[0];if(f)void loadSession(f);e.target.value='';}}/>{toast&&<div className="toast" role="status"><Check size={16}/>{toast}</div>}</div>;
}
